-- Arbeitsrecht Berufsbildung > Pflichten von Arbeitgebern > Vergütung zahlen (§ 17 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb einem Fachinformatiker eine Vergütung zahlen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 17 BBiG verpflichtet den Betrieb dazu"}, {"text": "Nein", "correct": false, "because": "Vergütung ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betrieb die Vergütung eines Fachinformatikers einbehalten, wenn er krank ist?', 2, '[{"text": "Nein", "correct": true, "because": "§ 17 BBiG garantiert die Vergütung auch bei Krankheit (§ 3 EntgFG)"}, {"text": "Ja", "correct": false, "because": "Krankheit rechtfertigt keine Kürzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Vergütung eines Fachinformatikers monatlich gezahlt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Monatliche Zahlung ist übliche Praxis nach § 17 BBiG"}, {"text": "Nein", "correct": false, "because": "Regelmäßige Zahlung ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Ausbildungsbetrieb die Vergütung eines Fachinformatikers reduzieren, wenn er schlecht arbeitet?', 2, '[{"text": "Nein", "correct": true, "because": "§ 17 BBiG schützt die volle Vergütung"}, {"text": "Ja", "correct": false, "because": "Kürzung ist nicht zulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Betrieb einem Fachinformatiker auch in der Probezeit eine Vergütung zahlen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 17 BBiG gilt unabhängig von der Probezeit"}, {"text": "Nein", "correct": false, "because": "Vergütung ist immer Pflicht"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Betrieb, einem Fachinformatiker eine Vergütung zu zahlen?', 2, '[{"text": "§ 17 BBiG", "correct": true, "because": "Regelt die Vergütungspflicht"}, {"text": "§ 14 BBiG", "correct": false, "because": "Bezieht sich auf andere Pflichten"}, {"text": "§ 22 BBiG", "correct": false, "because": "Regelt die Kündigung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn sein Betrieb die Vergütung nicht zahlt?', 3, '[{"text": "Den Betrieb darauf hinweisen und ggf. die IHK informieren", "correct": true, "because": "Rechtlicher Weg gemäß § 17 BBiG"}, {"text": "Es hinnehmen", "correct": false, "because": "Vergütung ist einklagbar"}, {"text": "Sofort kündigen", "correct": false, "because": "Nicht die erste Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regelung bestimmt die Höhe der Vergütung eines Fachinformatikers?', 3, '[{"text": "Tarifverträge oder betriebliche Vereinbarungen", "correct": true, "because": "§ 17 BBiG verweist darauf"}, {"text": "Persönliche Leistung", "correct": false, "because": "Leistung beeinflusst nicht die Grundvergütung"}, {"text": "Belieben des Betriebs", "correct": false, "because": "Nicht willkürlich festlegbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, die Vergütung eines Fachinformatikers zu zahlen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 17 BBiG legt dies fest"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule hat keine Zahlungspflicht"}, {"text": "Die IHK", "correct": false, "because": "IHK überwacht nur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb die Vergütung eines Fachinformatikers nicht zahlt?', 3, '[{"text": "Der Auszubildende kann sie einklagen", "correct": true, "because": "§ 17 BBiG ist einklagbar"}, {"text": "Die Vergütung verfällt", "correct": false, "because": "Anspruch bleibt bestehen"}, {"text": "Die Berufsschule übernimmt die Zahlung", "correct": false, "because": "Schule ist nicht verantwortlich"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Vergütung eines Fachinformatikers gemäß § 17 BBiG?', 4, '[{"text": "Monatliche Grundvergütung", "correct": true, "because": "Kernbestandteil der Vergütung"}, {"text": "Überstundenzuschläge", "correct": true, "because": "Falls tariflich geregelt"}, {"text": "Kosten für Arbeitsmittel", "correct": false, "because": "Betrieb trägt diese separat"}, {"text": "Sonderzahlungen wie Weihnachtsgeld", "correct": true, "because": "Wenn tariflich vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren können die Vergütung eines Fachinformatikers beeinflussen?', 3, '[{"text": "Tarifverträge", "correct": true, "because": "Häufige Grundlage nach § 17 BBiG"}, {"text": "Ausbildungsjahr", "correct": true, "because": "Vergütung steigt oft jährlich"}, {"text": "Persönliche Leistung", "correct": false, "because": "Nicht direkt relevant"}, {"text": "Betriebsgröße", "correct": true, "because": "Kann die Höhe variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Ausbildungsbetrieb bei der Vergütung eines Fachinformatikers beachten?', 4, '[{"text": "Regelmäßige Zahlung", "correct": true, "because": "Übliche Praxis nach § 17 BBiG"}, {"text": "Einhaltung von Tarifverträgen", "correct": true, "because": "Wenn anwendbar"}, {"text": "Kürzung bei Krankheit", "correct": false, "because": "Nicht zulässig"}, {"text": "Zahlung auch in der Probezeit", "correct": true, "because": "Pflicht ab Beginn"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Betrieb, der die Vergütung eines Fachinformatikers nicht zahlt?', 3, '[{"text": "Schadensersatzforderungen", "correct": true, "because": "Verletzung von § 17 BBiG"}, {"text": "Verwarnung durch die IHK", "correct": true, "because": "IHK kann einschreiten"}, {"text": "Automatische Schließung", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Zwangsvollstreckung bei Klage", "correct": true, "because": "Rechtlich durchsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'In welchen Fällen bleibt die Vergütung eines Fachinformatikers erhalten?', 3, '[{"text": "Während der Berufsschulzeit", "correct": true, "because": "§ 17 BBiG schützt den Anspruch"}, {"text": "Bei Krankheit", "correct": true, "because": "Entgeltfortzahlung gilt"}, {"text": "Nach Kündigung", "correct": false, "because": "Endet mit Ausbildung"}, {"text": "Während der Probezeit", "correct": true, "because": "Vergütung ab Beginn"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Betrieb muss einem Fachinformatiker eine Vergütung zahlen. b) Die Vergütung kann bei schlechter Leistung gekürzt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zahlung Pflicht, Kürzung nicht zulässig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Vergütung eines Fachinformatikers ist tariflich geregelt. b) § 17 BBiG garantiert eine Mindestvergütung.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Tarif nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch, keine Mindestsumme"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) kann richtig sein"}, {"text": "Beides falsch", "correct": true, "because": "Tarif optional, keine Mindestvergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Betrieb muss die Vergütung eines Fachinformatikers monatlich zahlen. b) Die Vergütung bleibt bei Krankheit erhalten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Monatlich üblich, Krankheit geschützt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Vergütung eines Fachinformatikers kann in Naturalien gezahlt werden. b) Ein Betrieb muss die Vergütung auch in der Probezeit zahlen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Naturalien nicht üblich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Probezeit geschützt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) § 17 BBiG verpflichtet den Betrieb zur Vergütung. b) Die Vergütung kann bei Berufsschulbesuch gekürzt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vergütung Pflicht, Kürzung unzulässig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

